// @vitest-environment node
/**
 * The projection engine's two whole-log reads (`candidates`, `preferences`) read only what they derive their answer from, and answer exactly as before.
 *
 * SNAPSHOTS. `service.engine.snapshots.json` holds, per history, `engine.candidates(...)` for every objective set the handler passes plus
 * `includeCovered` and the default limit, and `engine.preferences(...)` for every language, all as JSON. It was GENERATED BY THE UNMODIFIED ENGINE
 * (the whole-log reads, commit 1b82e03a):   RECORD_ENGINE_SNAPSHOTS=1 npx vitest run test/loading/service.engine.test.ts
 * Do not regenerate it to make a change pass: a difference means the answer changed. Every history runs over the memory store and over SQLite and both
 * must equal the same recording.
 *
 * BUDGET. Structure, not timing: with 3,000 lookups and 200 reviewed cards stored, `candidates` reads at most 1,200 event rows and makes at most 300 store
 * calls, and `preferences` reads at most 200 event rows.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { CONTRACT_VERSION } from '../../packages/repository-contract/src';
import type { Enrolment, FormAnalysis, GoEvent, LinguisticUnit, RepositoryStore, Tombstone, UnitAlias, UnitRelation } from '../../packages/repository-contract/src';
import { createProjectionEngine } from '../../packages/repository-engine/src';
import { createMemoryStore, openSqliteStore } from '../../packages/repository-store/src';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SNAPSHOTS = path.join(HERE, 'service.engine.snapshots.json');
const RECORD = process.env.RECORD_ENGINE_SNAPSHOTS === '1';

const NOW = '2026-10-08T12:00:00.000Z';
const NOW_MS = Date.parse(NOW);
const DAY = 86_400_000;
const L = 'learner-engine';
const ago = (days: number, minutes = 0): string => new Date(NOW_MS - days * DAY + minutes * 60_000).toISOString();

// ───────────────────────────── builders ─────────────────────────────
interface Opt { id?: string; at?: string; lang?: string; card?: string; sentence?: string; correctionOf?: string; evidence?: GoEvent['evidence']; app?: GoEvent['producer']['app']; source?: { kind: 'file'; title: string } }
let counter = 0;
function mk(kind: string, items: string[], payload: Record<string, unknown>, o: Opt = {}): GoEvent {
  const n = ++counter;
  return {
    id: o.id ?? `e-${String(n).padStart(5, '0')}`, v: CONTRACT_VERSION, learnerId: L, enrolmentId: `E-${o.lang ?? 'sq'}`, languageId: o.lang ?? 'sq', at: o.at ?? ago(1, n % 50),
    producer: { app: o.app ?? 'golearn-ext', version: '1', deviceId: 'D1' }, kind,
    subject: { itemIds: items, ...(o.card ? { cardId: o.card } : {}), ...(o.sentence ? { sentenceKey: o.sentence } : {}), ...(o.source ? { sourceRef: o.source } : {}) }, payload,
    ...(o.evidence ? { evidence: o.evidence } : { evidence: { quality: 'moderate', sourceReliability: 1 } }), ...(o.correctionOf ? { correctionOf: o.correctionOf } : {}),
  } as GoEvent;
}
const lookup = (u: string, o?: Opt): GoEvent => mk('SelectionLookedUp', [u], { surface: 'x', tokenCount: 1, contextKind: 'sentence', contextConfidence: 0.9, readerId: 'demo', helpShown: ['lemma'] }, o);
const encounter = (u: string, o?: Opt): GoEvent => mk('EncounterRecorded', [u], { contextKind: 'sentence', surface: 'x' }, o);
const assist = (u: string, payload: Record<string, unknown>, o?: Opt): GoEvent => mk('AssistanceRequested', [u], payload, o);
const play = (u: string, o?: Opt): GoEvent => mk('PronunciationPlayed', [u], { voice: 'synthetic' }, o);
const shown = (u: string, o?: Opt): GoEvent => mk('AnalysisShown', [u], { layers: ['lemma'] }, o);
const marked = (u: string, mark: string, o?: Opt): GoEvent => mk('ItemMarked', [u], { mark }, o);
const listened = (u: string, correct: boolean, o?: Opt): GoEvent => mk('ListeningAssessed', [u], { stimulus: 'word', voice: 'recorded', correct, responseMode: 'choice', answerShownBefore: false }, o);
const cardAdded = (u: string, dim: string | undefined, o?: Opt): GoEvent => mk('CardAdded', [u], { ...(dim ? { dimension: dim } : {}), lifecycle: 'create' }, { card: dim ? `card:${dim}:${u}` : `card:legacy:${u}`, ...o });
const cardRemoved = (u: string, dim: string | undefined, reason: string, extra: Record<string, unknown>, o?: Opt): GoEvent =>
  mk('CardRemoved', [u], { ...(dim ? { dimension: dim } : {}), reason, ...extra }, { card: dim ? `card:${dim}:${u}` : `card:legacy:${u}`, ...o });
const invalidated = (u: string, dim: string, o?: Opt): GoEvent => mk('ReviewItemInvalidated', [u], { reason: 'analysis-invalidated', dimension: dim }, { card: `card:${dim}:${u}`, ...o });
const review = (u: string, card: string, rating: number, previous: string | null | undefined, o: Opt = {}): GoEvent =>
  mk('CardReviewed', [u], {
    cardKind: 'recognition', family: 'written-recognition', assessmentDimension: 'written-recognition', rating, grade: rating === 1 ? 'again' : 'good', correct: rating > 1,
    outcome: rating > 1 ? 'correct' : 'incorrect', responseMode: 'typed', hinted: false, retrievalAttempted: true, ...(previous === undefined ? {} : { expectedPreviousReviewId: previous }),
  }, { card, app: 'gopractice-review', ...o });
const correction = (target: GoEvent, o: Opt = {}): GoEvent =>
  mk('CardReviewed', target.subject.itemIds!, { cardKind: 'recognition', grade: 'again', correct: false, hinted: false, rating: null, challenged: true }, {
    card: target.subject.cardId, app: 'gopractice-review', correctionOf: target.id, evidence: { quality: 'none' }, ...o });
const prefChanged = (key: string, value: unknown, o?: Opt): GoEvent => mk('PreferenceChanged', [], { key, value, origin: 'explicit' }, o);

const prov = { source: 'dictionary', ref: 'test', confidence: 0.9, validation: 'production-validated' } as never;
const unit = (unitId: string, kind: LinguisticUnit['kind'], extra: Partial<LinguisticUnit> = {}): LinguisticUnit => ({
  unitId, kind, languageId: unitId.split(':')[1], label: unitId.split(':').slice(2).join(':'), packId: 'pack:sq', packVersion: '1', provenance: prov, status: 'verified', createdAt: '2026-01-01T00:00:00.000Z', ...extra });
const realizes = (from: string, to: string, status: UnitRelation['status'] = 'verified'): UnitRelation => ({ fromId: from, relation: 'realizes', toId: to, confidence: 0.9, provenance: { source: 'rule', ref: 't', confidence: 0.9 } as never, status });
const analysis = (formId: string, status: FormAnalysis['status'], extra: Partial<FormAnalysis> = {}): FormAnalysis => ({
  analysisId: `an:${formId}:${status}`, formId, languageId: formId.split(':')[1], candidates: [{ confidence: 0.9, provenance: { source: 'rule', ref: 't', confidence: 0.9, validation: 'production-validated' } as never }],
  status, analyzerId: 'test', packId: 'pack:sq', packVersion: '1', createdAt: '2026-01-01T00:00:00.000Z', ...extra });

interface History {
  name: string;
  units?: LinguisticUnit[]; relations?: UnitRelation[]; analyses?: FormAnalysis[]; aliases?: UnitAlias[]; tombstones?: Tombstone[];
  events: GoEvent[];
  languages?: string[];
  /** Events are appended in this order (default: as listed), to separate `seq` order from `at` order. */
  goals?: Enrolment['goals'];
}

const CX = 'morph:sq:CX-acc', CY = 'morph:sq:CY-gen', CZ = 'morph:sq:CZ-dat', CV = 'morph:sq:CV-abl', CB = 'morph:sq:CB-edge', CW = 'morph:sq:CW-old';
const F = (n: number | string): string => `form:sq:f${n}`;
const W = (n: number): string => `lex:sq:w${n}`;
const baseUnits = (): LinguisticUnit[] => [
  ...Array.from({ length: 40 }, (_, i) => unit(F(i), 'form', i % 7 === 0 ? { frequency: { rank: 300 + i, source: 't' } } : {})),
  ...Array.from({ length: 24 }, (_, i) => unit(W(i), 'lexeme', i % 5 === 0 ? { frequency: { rank: 100 + i, source: 't' } } : i % 3 === 0 ? { frequency: { rank: 1800, source: 't' } } : {})),
  ...[CX, CY, CZ, CV, CB, CW].map((c) => unit(c, 'morph-construction', { label: c.split(':')[2] })),
];

function histories(): History[] {
  counter = 0;
  const out: History[] = [];

  // 1. lookups only: forms, lexemes, repeats, two constructions (one with enough forms, one without), analyses of several statuses
  {
    const events: GoEvent[] = [];
    for (let i = 0; i < 10; i++) events.push(lookup(F(i), { at: ago(1 + i * 0.5) }));
    for (let i = 10; i < 15; i++) for (let k = 0; k < 3; k++) events.push(lookup(F(i), { at: ago(2 + k) }));
    for (let i = 0; i < 12; i++) events.push(lookup(W(i), { at: ago(3 + i) }));
    out.push({
      name: 'lookups-only', events, units: baseUnits(),
      relations: [...[0, 1, 2, 3, 4, 5].map((i) => realizes(F(i), CX)), realizes(F(6), CY), realizes(F(7), CY), realizes(F(8), CX, 'invalidated'), realizes(F(9), CX, 'requires-review')],
      analyses: [analysis(F(0), 'verified'), analysis(F(1), 'unverified' as never), analysis(F(10), 'verified'), analysis(F(11), 'verified'), analysis(F(2), 'verified', { candidates: [] })],
    });
  }

  // 2. lookups plus encounters, frequency, goals that unlock other objectives
  {
    const events: GoEvent[] = [];
    for (let i = 0; i < 12; i++) events.push(lookup(F(i), { at: ago(0.5 + i) }));
    for (let i = 20; i < 30; i++) for (let k = 0; k < 4; k++) events.push(encounter(F(i), { at: ago(1 + k * 3) }));
    for (let i = 0; i < 24; i++) events.push(encounter(W(i), { at: ago(2 + (i % 9)) }));
    for (let i = 0; i < 6; i++) events.push(assist(F(30 + i), { assistance: 'gloss' }, { at: ago(5) }), assist(F(30 + i), { assistance: 'phrase' }, { at: ago(4) }));
    out.push({ name: 'lookups-and-encounters', events, units: baseUnits(), relations: [0, 1, 2, 3, 4].map((i) => realizes(F(i), CX)), analyses: [analysis(F(20), 'verified'), analysis(F(21), 'verified')],
      goals: [{ kind: 'reading' }, { kind: 'listening' }, { kind: 'writing' }] });
  }

  // 3. cards: review chains, a correction, a retraction (a corrected review), removals, an invalidation, a recent review, legacy cards, a card on a lexeme
  {
    const events: GoEvent[] = [];
    for (let i = 0; i < 12; i++) events.push(lookup(F(i), { at: ago(8 + i) }), lookup(F(i), { at: ago(7 + i) }));
    for (let i = 0; i < 8; i++) events.push(lookup(W(i), { at: ago(9 + i) }));
    events.push(cardAdded(F(0), 'readingRecognition', { at: ago(20) }), cardAdded(F(1), 'listeningRecognition', { at: ago(20) }), cardAdded(F(2), undefined, { at: ago(20) }));
    events.push(cardAdded(F(3), 'readingRecognition', { at: ago(30) }), cardRemoved(F(3), 'readingRecognition', 'suspended', {}, { at: ago(25) }));
    events.push(cardAdded(F(4), 'readingRecognition', { at: ago(30) }), cardRemoved(F(4), 'readingRecognition', 'snoozed', { until: ago(-5) }, { at: ago(10) }));
    events.push(cardAdded(F(5), 'readingRecognition', { at: ago(30) }), cardRemoved(F(5), 'readingRecognition', 'snoozed', { until: ago(5) }, { at: ago(10) }));
    events.push(cardAdded(F(6), 'readingRecognition', { at: ago(30) }), cardRemoved(F(6), 'readingRecognition', 'dismissed', {}, { at: ago(9) }));
    events.push(cardAdded(F(7), 'readingRecognition', { at: ago(30) }), invalidated(F(7), 'readingRecognition', { at: ago(8) }));
    events.push(cardAdded(F(8), 'readingRecognition', { at: ago(30) }), cardRemoved(F(8), 'readingRecognition', 'dismissed', {}, { at: ago(15) }), cardAdded(F(8), 'readingRecognition', { at: ago(12) }));
    events.push(cardAdded(W(0), 'readingRecognition', { at: ago(30) }), cardAdded(W(1), 'productiveRetrieval', { at: ago(30) }));
    const c0 = `card:readingRecognition:${F(0)}`;
    const r1 = review(F(0), c0, 3, null, { id: 'rv-0-1', at: ago(15) });
    const r2 = review(F(0), c0, 1, 'rv-0-1', { id: 'rv-0-2', at: ago(12) });
    const r3 = review(F(0), c0, 3, 'rv-0-2', { id: 'rv-0-3', at: ago(10) });
    events.push(r1, r2, r3, correction(r2, { id: 'rv-0-2c', at: ago(11.5) }), review(F(0), c0, 1, 'rv-0-3', { id: 'rv-0-4', at: ago(1.2) }));
    const c1 = `card:readingRecognition:${F(9)}`;
    events.push(review(F(9), c1, 3, null, { id: 'rv-9-1', at: ago(6) }), review(F(9), c1, 1, 'rv-9-1', { id: 'rv-9-2', at: ago(3) }), review(F(9), c1, 3, 'rv-9-2', { id: 'rv-9-3', at: ago(0.5) }));
    const cw = `card:readingRecognition:${W(2)}`;
    events.push(cardAdded(W(2), 'readingRecognition', { at: ago(30) }), review(W(2), cw, 3, null, { id: 'rv-w2-1', at: ago(0.2) }), review(W(2), cw, 3, 'rv-w2-1', { id: 'rv-w2-2', at: ago(0.1) }));
    events.push(mk('AssessmentAnswered', [F(10)], { constructionId: CX, task: 'interpret', correct: false, hinted: false }, { card: `card:grammaticalUnderstanding:${CX}`, app: 'gopractice-review', at: ago(4), id: 'as-1' }));
    out.push({ name: 'cards-chains-corrections', events, units: baseUnits(), relations: [0, 1, 2, 3].map((i) => realizes(F(i), CX)), analyses: [analysis(F(0), 'verified'), analysis(F(9), 'verified')],
      goals: [{ kind: 'reading' }, { kind: 'speaking' }, { kind: 'listening' }] });
  }

  // 4. struggles inside and outside the 30-day window, across kinds, with constructions at the edge
  {
    const events: GoEvent[] = [];
    // CZ: g0..g2 looked up 3 days ago (in), g3 only 45 days ago (out), g4 failed card review 10 days ago (in), g5 assistance 60 days ago (out)
    for (let i = 0; i < 3; i++) events.push(lookup(F(`g${i}`), { at: ago(3 + i) }));
    events.push(lookup(F('g3'), { at: ago(45) }));
    events.push(review(F('g4'), `card:readingRecognition:${F('g4')}`, 1, null, { id: 'rv-g4', at: ago(10) }));
    events.push(assist(F('g5'), { assistance: 'gloss' }, { at: ago(60) }));
    // CW: h0, h1 only outside the window; h2 has an old error (hasError counts whatever its age)
    events.push(lookup(F('h0'), { at: ago(40) }), lookup(F('h1'), { at: ago(41) }));
    events.push(review(F('h2'), `card:readingRecognition:${F('h2')}`, 1, null, { id: 'rv-h2', at: ago(50) }));
    // CV: k0 lookup, k1 a "new" mark, k2 a failed listening answer, all in the window
    events.push(lookup(F('k0'), { at: ago(5) }), marked(F('k1'), 'new', { at: ago(6) }), listened(F('k2'), false, { at: ago(7) }));
    // CB: the boundary, exactly 30 days (in), and 30 days + 1 minute (out), and a lookup 1 hour in the future
    events.push(lookup(F('b0'), { at: ago(30) }), lookup(F('b1'), { at: ago(30, -1) }), lookup(F('b2'), { at: ago(30, 1) }), lookup(F('b3'), { at: ago(-0.04) }), lookup(F('b4'), { at: ago(-2) }));
    // CY: a form struggling through a hinted review and through an analysis request (assisted)
    events.push(review(F('y0'), `card:readingRecognition:${F('y0')}`, 3, null, { id: 'rv-y0', at: ago(4) }));
    events.push(mk('CardReviewed', [F('y1')], { cardKind: 'recognition', grade: 'again', correct: false, hinted: true, rating: 1, family: 'written-recognition', responseMode: 'typed', outcome: 'incorrect', retrievalAttempted: true, expectedPreviousReviewId: null }, { card: `card:readingRecognition:${F('y1')}`, app: 'gopractice-review', at: ago(5), id: 'rv-y1' }));
    events.push(shown(F('y2'), { at: ago(2) }), assist(F('y2'), { assistance: 'sentence' }, { at: ago(2, 5) }));
    const ids = ['g0', 'g1', 'g2', 'g3', 'g4', 'g5', 'h0', 'h1', 'h2', 'k0', 'k1', 'k2', 'b0', 'b1', 'b2', 'b3', 'b4', 'y0', 'y1', 'y2'];
    out.push({
      name: 'struggles-window', events,
      units: [...ids.map((i) => unit(F(i), 'form')), ...[CX, CY, CZ, CV, CB, CW].map((c) => unit(c, 'morph-construction'))],
      relations: [
        ...['g0', 'g1', 'g2', 'g3', 'g4', 'g5'].map((i) => realizes(F(i), CZ)), ...['h0', 'h1', 'h2'].map((i) => realizes(F(i), CW)), ...['k0', 'k1', 'k2'].map((i) => realizes(F(i), CV)),
        ...['b0', 'b1', 'b2'].map((i) => realizes(F(i), CB)), ...['y0', 'y1', 'y2'].map((i) => realizes(F(i), CY)), realizes(F('b3'), CB), realizes(F('b4'), CX),
      ],
      analyses: ids.slice(0, 10).map((i) => analysis(F(i), 'verified')),
    });
  }

  // 5. aliases: old ids, a chain, an uncertain alias, a card and a review on an old id
  {
    const events: GoEvent[] = [];
    for (let i = 0; i < 6; i++) events.push(lookup(F(`old${i}`), { at: ago(2 + i) }), lookup(F(i), { at: ago(2 + i, 3) }));
    events.push(lookup(F('older0'), { at: ago(2) }), lookup(F('maybe'), { at: ago(2) }), lookup(F('maybe'), { at: ago(3) }));
    events.push(cardAdded(F('old1'), 'readingRecognition', { at: ago(20) }));
    events.push(review(F('old2'), `card:readingRecognition:${F('old2')}`, 1, null, { id: 'rv-old2', at: ago(4) }));
    const alias = (o: string, n: string, mapping: 'certain' | 'uncertain' = 'certain'): UnitAlias => ({ oldId: o, newId: n, mapping, packVersion: '1', reason: 'renamed', confidence: 0.9, createdAt: '2026-02-01T00:00:00.000Z' } as never);
    out.push({
      name: 'aliases', events, units: baseUnits(), aliases: [...[0, 1, 2, 3, 4, 5].map((i) => alias(F(`old${i}`), F(i))), alias(F('older0'), F('old0')), alias(F('maybe'), F(30), 'uncertain')],
      relations: [0, 1, 2, 3, 4].map((i) => realizes(F(i), CX)), analyses: [analysis(F(0), 'verified'), analysis(F(2), 'verified')],
    });
  }

  // 6. two languages
  {
    const events: GoEvent[] = [];
    for (let i = 0; i < 8; i++) events.push(lookup(F(i), { at: ago(2 + i) }), lookup(`form:el:e${i}`, { lang: 'el', at: ago(1 + i) }));
    for (let i = 0; i < 4; i++) events.push(assist(`form:el:e${i}`, { assistance: 'transliteration' }, { lang: 'el', at: ago(2) }), assist(`form:el:e${i}`, { assistance: 'gloss', depth: 'explanatory' }, { lang: 'el', at: ago(3) }));
    events.push(cardAdded(`form:el:e0`, 'readingRecognition', { lang: 'el', at: ago(30) }), cardAdded(F(0), 'readingRecognition', { at: ago(30) }));
    events.push(prefChanged('terminology', 'grammatical', { lang: 'el', at: ago(9) }), prefChanged('visualAssistance', 'more', { lang: 'sq', at: ago(8) }));
    events.push(review(`form:el:e1`, 'card:readingRecognition:form:el:e1', 1, null, { lang: 'el', id: 'rv-el1', at: ago(4) }));
    out.push({
      name: 'two-languages', events, languages: ['sq', 'el'],
      units: [...baseUnits(), ...Array.from({ length: 8 }, (_, i) => unit(`form:el:e${i}`, 'form', { packId: 'pack:el' })), unit('morph:el:CE', 'morph-construction', { packId: 'pack:el' })],
      relations: [...[0, 1, 2, 3].map((i) => realizes(`form:el:e${i}`, 'morph:el:CE')), ...[0, 1, 2].map((i) => realizes(F(i), CX))],
    });
  }

  // 7. tombstones: one event, a source, a range
  {
    const events: GoEvent[] = [];
    const src = { kind: 'file' as const, title: 'A private book' };
    for (let i = 0; i < 8; i++) events.push(lookup(F(i), { at: ago(2 + i), id: `tb-l${i}` }));
    for (let i = 8; i < 14; i++) events.push(lookup(F(i), { at: ago(3), source: src, id: `tb-s${i}` }));
    for (let i = 14; i < 20; i++) events.push(lookup(F(i), { at: ago(20 + i % 3), id: `tb-r${i}` }));
    events.push(assist(F(0), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(2), id: 'tb-a0' }), assist(F(0), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(2, 1), id: 'tb-a1' }), assist(F(0), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(2, 2), id: 'tb-a2' }));
    events.push(cardAdded(F(1), 'readingRecognition', { at: ago(25), id: 'tb-c1' }), review(F(1), `card:readingRecognition:${F(1)}`, 1, null, { id: 'tb-rv1', at: ago(0.3) }));
    const t = (tombstoneId: string, scope: Tombstone['scope']): Tombstone => ({ tombstoneId, learnerId: L, scope, createdAt: ago(0.1) });
    out.push({
      name: 'tombstones', events, units: baseUnits(), relations: [0, 1, 2, 3, 8, 9, 10].map((i) => realizes(F(i), CX)),
      tombstones: [t('t1', { kind: 'event', id: 'tb-l2' }), t('t2', { kind: 'source', sourceRef: src }), t('t3', { kind: 'range', from: ago(21), to: ago(19) }), t('t4', { kind: 'event', id: 'tb-a1' }), t('t5', { kind: 'event', id: 'tb-rv1' })],
    });
  }

  // 8. preferences: explicit (valid, invalid, latest wins), inferred (depth, transliteration, audio first), per sentence, with audio so the sentence order matters
  {
    const events: GoEvent[] = [];
    events.push(prefChanged('explanationDepth', 'label', { at: ago(40) }), prefChanged('explanationDepth', 'nonsense', { at: ago(39) }), prefChanged('terminology', 'plain', { at: ago(38) }), prefChanged('accessibility', ['large-text'], { at: ago(37) }));
    for (let i = 0; i < 4; i++) events.push(assist(F(i), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(10 + i) }));
    for (let i = 0; i < 3; i++) events.push(assist(F(i), { assistance: 'transliteration' }, { at: ago(12 + i) }));
    for (let s = 0; s < 4; s++) events.push(play(F(s), { sentence: `S${s}`, at: ago(9, s) }), lookup(F(s), { sentence: `S${s}`, at: ago(9, s + 10) }));
    events.push(lookup(F(10), { sentence: 'S10', at: ago(8) }), play(F(10), { sentence: 'S10', at: ago(8, 5) }));
    events.push(shown(F(11), { sentence: 'S11', at: ago(7) }), play(F(11), { sentence: 'S11', at: ago(7, 5) }));
    events.push(assist(F(12), { assistance: 'pronunciation' }, { sentence: 'S12', at: ago(6) }), play(F(12), { sentence: 'S12', at: ago(6, 5) }));
    for (let i = 0; i < 30; i++) events.push(lookup(F(i % 20), { at: ago(1 + i / 10) }));
    out.push({ name: 'preferences-with-audio', events, units: baseUnits() });
  }

  // 8b. audio in every sentence, but an OLDER help event came first in each of four sentences (so no sentence is audio-first), and in two more the audio is first
  {
    const events: GoEvent[] = [];
    for (let s = 0; s < 4; s++) events.push(play(F(s), { sentence: `T${s}`, at: ago(9, s) }), lookup(F(s), { sentence: `T${s}`, at: ago(60 + s) }));
    for (let s = 4; s < 6; s++) events.push(play(F(s), { sentence: `T${s}`, at: ago(9, s) }), lookup(F(s), { sentence: `T${s}`, at: ago(2 + s) }));
    for (let i = 0; i < 12; i++) events.push(lookup(F(10 + i), { at: ago(0.2 + i / 10) }));
    out.push({ name: 'preferences-audio-old-help', events, units: baseUnits() });
  }

  // 9. preferences without audio; the newest event by `at` was appended FIRST (seq order differs from at order)
  {
    const events: GoEvent[] = [];
    events.push(lookup(F(1), { at: ago(0.01), id: 'pn-newest' }));
    for (let i = 0; i < 20; i++) events.push(lookup(F(i), { at: ago(5 + i), id: `pn-${i}` }));
    events.push(assist(F(1), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(4) }), assist(F(1), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(5) }), assist(F(1), { assistance: 'gloss', depth: 'explanatory' }, { at: ago(6) }));
    events.push(shown(F(2), { at: ago(0.5) }));
    out.push({ name: 'preferences-no-audio-recent', events, units: baseUnits() });
  }

  // 10. preferences without audio, every lookup older than a month (the recency window must widen), appended newest-last and newest-first mixed
  {
    const events: GoEvent[] = [];
    for (const d of [90, 70, 35, 60, 45, 120]) events.push(lookup(F(d % 10), { at: ago(d) }));
    events.push(shown(F(2), { at: ago(80) }), assist(F(3), { assistance: 'transliteration' }, { at: ago(50) }));
    out.push({ name: 'preferences-no-audio-old', events, units: baseUnits() });
  }

  // 11. nothing at all, and only another language's events
  out.push({ name: 'empty', events: [], units: baseUnits(), languages: ['sq'] });
  out.push({ name: 'only-other-language', events: [lookup('form:el:e0', { lang: 'el', at: ago(2) }), play('form:el:e0', { lang: 'el', sentence: 'x', at: ago(3) })], units: baseUnits(), languages: ['sq', 'el'] });

  // 12. a learner tombstone
  out.push({ name: 'tombstone-learner', events: [lookup(F(1), { at: ago(2) }), lookup(F(2), { at: ago(3) })], units: baseUnits(), tombstones: [{ tombstoneId: 'tl', learnerId: L, scope: { kind: 'learner' }, createdAt: ago(1) }] });
  return out;
}

// ───────────────────────────── harness ─────────────────────────────
async function load(kind: 'memory' | 'sqlite', h: History): Promise<RepositoryStore> {
  const store = kind === 'memory' ? createMemoryStore({ now: () => NOW }) : openSqliteStore(':memory:', { now: () => NOW });
  await store.putLearner({ learnerId: L, createdAt: '2026-01-01T00:00:00.000Z' });
  for (const lang of h.languages ?? ['sq']) {
    await store.putEnrolment({ enrolmentId: `E-${lang}`, learnerId: L, languageId: lang, packId: `pack:${lang}`, packVersion: '1', goals: h.goals ?? [{ kind: 'reading' }], startedAt: '2026-01-01T00:00:00.000Z' });
  }
  if (h.units?.length) await store.putUnits(h.units);
  if (h.relations?.length) await store.putRelations(h.relations);
  if (h.analyses?.length) await store.putAnalyses(h.analyses);
  if (h.aliases?.length) await store.putAliases?.(h.aliases);
  for (let i = 0; i < h.events.length; i += 200) {
    const outcomes = await store.append(L, h.events.slice(i, i + 200));
    const bad = outcomes.find((o) => !o.stored);
    if (bad) throw new Error(`${h.name}: event refused ${JSON.stringify(bad)}`);
  }
  for (const t of h.tombstones ?? []) await store.putTombstone(t);
  return store;
}

const OBJECTIVE_SETS: Array<[string, string[]]> = [['none', []], ['listening', ['listeningRecognition']], ['retrieval+grammar', ['productiveRetrieval', 'grammaticalUnderstanding']], ['four', ['listeningRecognition', 'productiveRetrieval', 'contextualProduction', 'phraseComprehension']]];

async function record(kind: 'memory' | 'sqlite', h: History): Promise<unknown> {
  const store = await load(kind, h);
  const engine = createProjectionEngine({ store, now: () => NOW });
  const result: Record<string, unknown> = {};
  for (const lang of h.languages ?? ['sq']) {
    for (const [name, dims] of OBJECTIVE_SETS) {
      const notes: string[] = [];
      result[`candidates:${lang}:${name}`] = { list: await engine.candidates(L, `E-${lang}`, { limit: Number.MAX_SAFE_INTEGER, now: NOW, objectiveDimensions: dims as never, notes }), notes };
    }
    const notes: string[] = [];
    result[`candidates:${lang}:covered-default-limit`] = { list: await engine.candidates(L, `E-${lang}`, { now: NOW, includeCovered: true, notes }), notes };
    result[`candidates:${lang}:limit-3`] = { list: await engine.candidates(L, `E-${lang}`, { limit: 3 }), notes: [] };
    result[`preferences:${lang}`] = await engine.preferences(L, lang);
  }
  result['preferences:all'] = await engine.preferences(L);
  result['candidates:unknown-enrolment'] = await engine.candidates(L, 'E-nope', { now: NOW });
  await store.close();
  return JSON.parse(JSON.stringify(result));
}

const all = histories();

describe('engine reads: identical answers over the memory and SQLite stores', () => {
  if (RECORD) {
    it('RECORD: writes the snapshots from the engine as it is now', async () => {
      const snaps: Record<string, unknown> = {};
      for (const h of all) {
        const mem = await record('memory', h);
        const sql = await record('sqlite', h);
        expect(sql, `${h.name}: memory and sqlite agree`).toEqual(mem);
        snaps[h.name] = mem;
      }
      fs.writeFileSync(SNAPSHOTS, JSON.stringify(snaps, null, 1) + '\n');
    });
    return;
  }
  const snaps = JSON.parse(fs.readFileSync(SNAPSHOTS, 'utf8')) as Record<string, Record<string, unknown>>;
  it('every history has a recording, and the recordings are not trivial', () => {
    expect(Object.keys(snaps).sort()).toEqual(all.map((h) => h.name).sort());
    const nonEmpty = (name: string): number => (snaps[name]['candidates:sq:none'] as { list: unknown[] }).list.length;
    expect(nonEmpty('lookups-only')).toBeGreaterThan(10);
    expect(nonEmpty('struggles-window')).toBeGreaterThan(5);
    const leverage = (name: string): number => (snaps[name]['candidates:sq:none'] as { list: Array<{ reasons: Array<{ rule: string }> }> }).list.filter((c) => c.reasons.some((r) => r.rule === 'grammaticalLeverage')).length;
    expect(leverage('lookups-only')).toBeGreaterThan(0);
    expect(leverage('struggles-window')).toBeGreaterThan(0);
  });
  describe.each(all.map((h) => [h.name, h] as const))('%s', (name, h) => {
    it.each(['memory', 'sqlite'] as const)('%s store: candidates and preferences equal the recording', async (kind) => {
      expect(await record(kind, h)).toEqual(snaps[name]);
    });
  });
});

// ───────────────────────────── budget: structure, not timing ─────────────────────────────
interface Meter { calls: Record<string, number>; total: number; eventRows: number }
function metered(store: RepositoryStore): { store: RepositoryStore; meter: Meter } {
  const meter: Meter = { calls: {}, total: 0, eventRows: 0 };
  const proxy = new Proxy(store, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);
      if (typeof value !== 'function' || typeof prop !== 'string') return value;
      return async (...args: unknown[]) => {
        meter.calls[prop] = (meter.calls[prop] ?? 0) + 1;
        meter.total++;
        const out = await (value as (...a: unknown[]) => Promise<unknown>).apply(target, args);
        if ((prop === 'list' || prop === 'listEventsOfUnits') && Array.isArray(out)) meter.eventRows += out.length;
        return out;
      };
    },
  });
  return { store: proxy, meter };
}

async function bigHistory(withConstruction: boolean): Promise<RepositoryStore> {
  counter = 0;
  const store = openSqliteStore(':memory:', { now: () => NOW });
  await store.putLearner({ learnerId: L, createdAt: '2026-01-01T00:00:00.000Z' });
  await store.putEnrolment({ enrolmentId: 'E-sq', learnerId: L, languageId: 'sq', packId: 'pack:sq', packVersion: '1', goals: [{ kind: 'reading' }], startedAt: '2026-01-01T00:00:00.000Z' });
  const units = Array.from({ length: 400 }, (_, i) => unit(W(i), 'lexeme', i % 9 === 0 ? { frequency: { rank: 200 + i, source: 't' } } : {}));
  await store.putUnits([...units, unit(CX, 'morph-construction')]);
  if (withConstruction) {
    await store.putUnits([0, 1, 2].map((i) => unit(F(i), 'form')));
    await store.putRelations([0, 1, 2].map((i) => realizes(F(i), CX)));
  }
  const events: GoEvent[] = [];
  // 3,000 lookups over 100 days (about 900 inside the 30-day window), the newest a few minutes ago
  for (let i = 0; i < 3000; i++) events.push(lookup(W(i % 400), { at: ago(0.003 + (i / 3000) * 100), id: `big-l${i}` }));
  // 200 reviewed cards: added, then reviewed once a week ago
  for (let u = 0; u < 200; u++) {
    events.push(cardAdded(W(u), 'readingRecognition', { at: ago(60), id: `big-ca${u}` }));
    events.push(review(W(u), `card:readingRecognition:${W(u)}`, u % 5 ? 3 : 1, null, { id: `big-rv${u}`, at: ago(7 + (u % 3)) }));
  }
  if (withConstruction) for (let i = 0; i < 3; i++) events.push(lookup(F(i), { at: ago(2), id: `big-f${i}` }));
  for (let i = 0; i < events.length; i += 500) {
    const outcomes = await store.append(L, events.slice(i, i + 500));
    if (outcomes.some((o) => !o.stored)) throw new Error('seed refused');
  }
  return store;
}

describe('engine reads: the budget (3,000 lookups, 200 reviewed cards)', () => {
  it('one candidates call reads at most 1,200 event rows and makes at most 300 store calls', async () => {
    const raw = await bigHistory(false);
    const engine0 = createProjectionEngine({ store: raw, now: () => NOW });
    await engine0.knowledge(L); // the projection is current, as it is after any earlier request
    const { store, meter } = metered(raw);
    const engine = createProjectionEngine({ store, now: () => NOW });
    const list = await engine.candidates(L, 'E-sq', { limit: Number.MAX_SAFE_INTEGER, now: NOW });
    expect(list.length).toBeGreaterThan(50);
    expect(meter.eventRows, JSON.stringify(meter.calls)).toBeLessThanOrEqual(1200);
    expect(meter.total, JSON.stringify(meter.calls)).toBeLessThanOrEqual(300);
  });

  it('one preferences call reads at most 200 event rows', async () => {
    const raw = await bigHistory(false);
    const { store, meter } = metered(raw);
    const engine = createProjectionEngine({ store, now: () => NOW });
    const prefs = await engine.preferences(L, 'sq');
    expect(prefs.learnerId).toBe(L);
    expect(meter.eventRows, JSON.stringify(meter.calls)).toBeLessThanOrEqual(200);
  });

  it('with a construction of three forms the struggle window is needed: it is still bounded by kinds and the window, and the answer holds', async () => {
    const raw = await bigHistory(true);
    const engine0 = createProjectionEngine({ store: raw, now: () => NOW });
    await engine0.knowledge(L);
    const { store, meter } = metered(raw);
    const engine = createProjectionEngine({ store, now: () => NOW });
    const list = await engine.candidates(L, 'E-sq', { limit: Number.MAX_SAFE_INTEGER, now: NOW });
    expect(list.find((c) => c.unitId === CX)?.explains).toEqual([F(0), F(1), F(2)]);
    expect(meter.eventRows, JSON.stringify(meter.calls)).toBeLessThan(3000 + 400);
    expect(meter.total, JSON.stringify(meter.calls)).toBeLessThanOrEqual(300);
  });
});

// ───────────────────────────── the struggle kinds list stays complete ─────────────────────────────
describe('engine reads: the event kinds read for struggles', () => {
  it('no other kind of event can produce a struggle observation, under any payload variant; each listed kind can', async () => {
    const { EVENT_KINDS, ITEM_MARKS } = await import('../../packages/repository-contract/src').then((m) => ({ EVENT_KINDS: m.EVENT_KINDS, ITEM_MARKS: (m as unknown as { ITEM_MARKS?: readonly string[] }).ITEM_MARKS }));
    const { observationsOf, isStruggleObservation, STRUGGLE_EVENT_KINDS } = await import('../../packages/repository-engine/src');
    const marks = ITEM_MARKS ?? ['new', 'seen', 'learning', 'recognized', 'familiar', 'known', 'automatic', 'productive', 'saved', 'ignore'];
    const kinds = Object.values(EVENT_KINDS).flat() as string[];
    const bools = [true, false];
    const canStruggle = new Set<string>();
    for (const kind of kinds) {
      for (const correct of bools) for (const hinted of bools) for (const assisted of bools) for (const mark of marks) for (const assistance of ['gloss', 'phrase', 'sentence', 'pronunciation', 'transliteration'])
        for (const cardKind of ['recognition', 'recall', 'cloze']) for (const usedCorrectly of [true, false, 'unjudged']) for (const helpUsed of bools) {
          const e = mk(kind, ['form:sq:probe', 'phrase:sq:probe'], {
            correct, hinted, assisted, mark, assistance, cardKind, usedCorrectly, helpUsed, answerShownBefore: false, grade: correct ? 'good' : 'again', rating: correct ? 3 : 1, outcome: correct ? 'correct' : 'incorrect',
            constructionId: CX, task: 'interpret', stimulus: 'word', voice: 'recorded', responseMode: 'choice', mode: 'free', scope: 'sentence', layers: ['lemma'], depth: 'explanatory', key: 'k', value: 'v',
            tokenCount: 1, contextKind: 'sentence', contextConfidence: 1, readerId: 'r', helpShown: ['lemma'], surface: 'x', origin: 'explicit',
          });
          if (observationsOf(e).some(isStruggleObservation)) canStruggle.add(kind);
        }
    }
    expect([...canStruggle].sort()).toEqual([...STRUGGLE_EVENT_KINDS].sort());
  });
});
